    body: '[1~3] 다음 글을 읽고 물음에 답하시오.<div class="passage" style="font-style:normal">경제학에서 어떤 선택의 비용을 따질 때는 지갑에서 나간 돈만 보지 않는다. 무엇인가를 선택하면 다른 것을 포기해야 하는데, 포기한 여러 대안 가운데 가장 가치가 큰 것의 가치를 그 선택의 기회비용이라고 한다. 예를 들어 주말 3시간 동안 시간당 1만 원을 받는 아르바이트를 할 수 있었는데 그 시간에 영화를 보았다면, 그리고 그 아르바이트가 포기한 대안 가운데 가장 가치가 컸다면, 영화의 기회비용에는 영화표 값뿐 아니라 포기한 아르바이트 수입 3만 원도 들어간다. 이처럼 기회비용에는 실제로 돈이 나가는 명시적 비용과, 돈이 나가지는 않지만 포기한 이득인 암묵적 비용이 함께 포함된다.<br>한편 이미 지출하여 어떤 선택을 하더라도 되찾을 수 없는 비용을 매몰 비용이라고 한다. 환불이 안 되는 공연표를 이미 샀다면, 공연을 보러 가든 가지 않든 그 표 값은 돌아오지 않는다. 따라서 합리적으로 선택하려면 매몰 비용은 고려하지 말고, 앞으로 각 대안에서 새로 얻게 될 편익과 새로 치르게 될 비용만 비교해야 한다. 그런데 사람들은 이미 들인 돈이나 시간이 아까워 손해가 예상되는 일을 계속하는 경우가 많다. 이를 매몰 비용의 오류라고 한다. 수익이 나지 않을 것이 분명해진 사업에 그동안 들인 투자금이 아까워 계속 돈을 쏟아붓는 것이 그 예이다. 매몰 비용은 이미 정해진 과거의 일이며, 선택이 바꿀 수 있는 것은 미래뿐이다.</div>윗글의 내용과 일치하는 것은?',
