    body: '다음 글의 제목으로 가장 적절한 것은?<div class="passage">Most of us picture the world with north at the top, and it is easy to assume that maps have always been drawn this way. In fact, nothing in nature makes north “up.” The Earth floats in space, where up and down have no fixed meaning. Many medieval European maps placed east at the top, since that was the direction of the rising sun. The very word “orientation” comes from this practice of facing the Orient, or the east. Some well-known maps made in the Islamic world even placed south at the top. The north-up arrangement became standard only gradually, partly because influential European mapmakers adopted it and their maps spread widely. What feels like a natural fact, then, is really a habit we have inherited.</div>',
